// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { DemoStage, Label, PanelChrome, type Build } from '@/app/demos/stage'

import { CAPTIONS, MATCHES, PATTERN, REPLACEMENT, SAMPLE } from './script'

const NODES = [
  { x: 34, w: 104, label: 'group 1 · \\w+', color: '#a78bfa', loop: true },
  { x: 156, w: 34, label: '@', color: '#9ca3af', loop: false },
  { x: 208, w: 104, label: 'group 2 · \\w+', color: '#22d3ee', loop: true },
  { x: 330, w: 52, label: '.com', color: '#9ca3af', loop: false },
]

const build: Build = ({ tl, q, qa, step, final, move, click, type, count, wait, cursorOut }) => {
  step(0)
  move('pattern', { at: 0.3, ax: 0.15 })
  click('pattern')
  type('pattern-text', PATTERN, { speed: 0.05 })
  tl.fromTo(
    q('rail'),
    { drawSVG: '0%' },
    { drawSVG: '100%', duration: 1, ease: 'power1.inOut' },
    '<0.1',
  )
  tl.fromTo(
    qa('node'),
    { scale: 0, opacity: 0, transformOrigin: '50% 50%' },
    { scale: 1, opacity: 1, duration: 0.35, stagger: 0.18, ease: 'back.out(2.4)' },
    '<0.15',
  )
  tl.fromTo(qa('loop'), { drawSVG: '0%' }, { drawSVG: '100%', duration: 0.4, stagger: 0.3 }, '<0.2')

  step(1, '+=0.3')
  tl.to(qa('match'), { backgroundColor: 'rgba(251,191,36,0.28)', duration: 0.25, stagger: 0.15 })
  count('count', MATCHES.length, { at: '<', duration: 0.5 })
  cursorOut('<')

  step(2, '+=0.4')
  tl.to(qa('match'), { backgroundColor: 'rgba(251,191,36,0)', duration: 0.2 })
  tl.to(qa('g1'), { backgroundColor: 'rgba(167,139,250,0.35)', duration: 0.25, stagger: 0.08 }, '<')
  tl.to(
    qa('g2'),
    { backgroundColor: 'rgba(34,211,238,0.3)', duration: 0.25, stagger: 0.08 },
    '<0.1',
  )
  tl.fromTo(
    qa('group-row'),
    { opacity: 0, y: 6 },
    { opacity: 1, y: 0, duration: 0.3, stagger: 0.08 },
    '<0.2',
  )

  step(3, '+=0.5')
  move('replace', { ax: 0.15 })
  click('replace')
  type('replace-text', REPLACEMENT, { speed: 0.06 })
  tl.to(q('groups'), { opacity: 0, duration: 0.2 })
  tl.set(q('preview'), { opacity: 1 })
  tl.fromTo(
    qa('preview-row'),
    { opacity: 0, x: 8 },
    { opacity: 1, x: 0, duration: 0.3, stagger: 0.08 },
  )
  cursorOut('+=0.2')
  final()
  wait(1.4)
}

export default function Demo() {
  return (
    <DemoStage
      label="Regex Toolkit demo: pattern entry, match list with groups, and replace preview (illustrative layout)"
      steps={CAPTIONS}
      build={build}
    >
      <PanelChrome
        aside={
          <span className="rounded-full border border-line-strong px-2.5 py-1 font-mono text-[10px]">
            <span data-d="count" className="text-amber">
              0
            </span>{' '}
            matches
          </span>
        }
      >
        <div className="flex h-full flex-col gap-2.5">
          <div
            data-d="pattern"
            className="flex h-8 items-center rounded-lg border border-line bg-canvas/80 px-2.5 font-mono text-[11.5px]"
          >
            <span className="text-muted">/</span>
            <span data-d="pattern-text" className="demo-caret text-violet" />
            <span className="text-muted">/g</span>
          </div>
          <svg viewBox="0 0 416 62" className="h-[62px] w-full">
            <path
              data-d="rail"
              d="M 6 38 H 410"
              fill="none"
              stroke="rgba(255,255,255,0.25)"
              strokeWidth="1.5"
            />
            <circle cx="6" cy="38" r="3.5" fill="#f4f4f6" />
            <circle cx="410" cy="38" r="3.5" fill="#f4f4f6" />
            {NODES.map((node) => (
              <g key={node.label}>
                {node.loop ? (
                  <path
                    data-d="loop"
                    d={`M ${node.x + node.w - 6} 38 C ${node.x + node.w + 8} 38, ${node.x + node.w + 8} 8, ${node.x + node.w / 2} 8 C ${node.x - 8} 8, ${node.x - 8} 38, ${node.x + 6} 38`}
                    fill="none"
                    stroke={node.color}
                    strokeOpacity="0.5"
                    strokeWidth="1.2"
                  />
                ) : null}
                <g data-d="node">
                  <rect
                    x={node.x}
                    y="27"
                    width={node.w}
                    height="22"
                    rx="6"
                    fill="#0b0b11"
                    stroke={node.color}
                    strokeWidth="1.4"
                  />
                  <text
                    x={node.x + node.w / 2}
                    y="42"
                    textAnchor="middle"
                    fontSize="10"
                    fontFamily="ui-monospace, monospace"
                    fill={node.color}
                  >
                    {node.label}
                  </text>
                </g>
              </g>
            ))}
          </svg>
          <div className="rounded-xl border border-line bg-canvas/80 px-3 py-2 font-mono text-[11px] leading-[22px] text-ink-soft">
            {SAMPLE.map((line, row) => (
              <p key={row}>
                {line.map((segment, index) =>
                  typeof segment === 'string' ? (
                    <span key={index}>{segment}</span>
                  ) : (
                    <span key={index} data-d="match" className="rounded px-px text-ink">
                      <span data-d="g1" className="rounded-sm">
                        {segment.user}
                      </span>
                      @
                      <span data-d="g2" className="rounded-sm">
                        {segment.domain}
                      </span>
                      .com
                    </span>
                  ),
                )}
              </p>
            ))}
          </div>
          <div className="grid min-h-0 flex-1 grid-cols-[150px_1fr] gap-2.5">
            <div
              data-d="replace"
              className="h-8 self-start rounded-lg border border-line bg-canvas/80 px-2.5 py-1.5 font-mono text-[11px]"
            >
              <span data-d="replace-text" className="text-emerald" />
            </div>
            <div className="relative">
              <div data-d="groups" className="space-y-1 font-mono text-[10px]">
                <Label>Groups</Label>
                {MATCHES.map((match) => (
                  <p key={match.user} data-d="group-row" className="opacity-0">
                    <span className="rounded bg-[#a78bfa]/25 px-1 text-[#c4b5fd]">
                      $1 {match.user}
                    </span>{' '}
                    <span className="rounded bg-cyan/20 px-1 text-cyan">$2 {match.domain}</span>
                  </p>
                ))}
              </div>
              <div
                data-d="preview"
                className="absolute inset-0 space-y-1 font-mono text-[10.5px] opacity-0"
              >
                <Label>Preview</Label>
                {MATCHES.map((match) => (
                  <p key={match.user} data-d="preview-row" className="text-ink">
                    {match.user} at {match.domain}
                  </p>
                ))}
              </div>
            </div>
          </div>
        </div>
      </PanelChrome>
    </DemoStage>
  )
}
